// =====================================================================
//  Turn each Notion row into a lead the Rules Brain can score.
//
//  EDIT THIS LIST if your Notion columns have different names.
//  Left side  = the exact column name in your Notion database.
//  Right side = the fact name the "lead_scoring" rule pack looks for.
// =====================================================================
const COLUMN_TO_FACT = {
  "Name": "name",
  "Email": "email",
  "Company": "company",
  "Company Size": "company_size",
  "Budget": "budget",
  "Role": "role",
  "Timeline": "timeline",
  "Source": "source",
  "Message": "message",
};

// Facts that are the same for every lead (used in the draft reply).
// Leave a value as "" and the draft will show DATA NEEDED there.
const EXTRA_FACTS = {
  sender_name: "",
  booking_link: "",
  resources_link: "",
};

// Which rule pack to use (must match a name in the Rules Brain).
const RULESET = "lead_scoring";

// =====================================================================
//  You should not need to edit below this line.
// =====================================================================

// Reads the plain value out of any common Notion column type.
// Returns "" when the cell is empty, so the Brain marks it DATA NEEDED.
function readCell(prop) {
  if (!prop) return "";
  switch (prop.type) {
    case "title":
    case "rich_text":
      return (prop[prop.type] || []).map((t) => t.plain_text).join("").trim();
    case "number":       return prop.number === null ? "" : prop.number;
    case "select":
    case "status":       return prop[prop.type] ? prop[prop.type].name : "";
    case "multi_select": return (prop.multi_select || []).map((o) => o.name);
    case "email":        return prop.email || "";
    case "phone_number": return prop.phone_number || "";
    case "url":          return prop.url || "";
    case "checkbox":     return prop.checkbox;
    case "date":         return prop.date ? prop.date.start : "";
    case "formula": {
      const f = prop.formula || {};
      return f[f.type] === null || f[f.type] === undefined ? "" : f[f.type];
    }
    default:             return "";
  }
}

const rows = $input.first().json.results || [];
return rows.map((page) => {
  const facts = { ...EXTRA_FACTS };
  for (const [column, fact] of Object.entries(COLUMN_TO_FACT)) {
    facts[fact] = readCell(page.properties[column]);
  }
  return {
    json: {
      pageId: page.id,
      pageUrl: page.url,
      task: "Score inbound lead",
      ruleset: RULESET,
      facts,
    },
  };
});

